#!/usr/bin/env bash
# Rebuild and reinstall the host APK for a title that is already installed.
#
# Why this exists: `gradlew assembleRelease` on its own produces an APK with no
# assets/launch.json. The file is generated by `s2a/cli.py build` into a staging
# directory and handed to Gradle as -Ps2aAssets, so it is not in the source tree.
# Installing such an APK makes the app refuse to start with
# "无法启动：launch.json" and offers to import a game.s2a instead, which drops
# into first-run setup and looks like a broken build.
#
# This script recovers the descriptor from the APK already on the device
# (or from a product directory given as argument 4), then rebuilds with the same
# application id, display name and asset set. Only the Java and native code
# change; game data, saves and imports live in app-private storage and survive
# an `install -r`.
#
# Usage: rebuild-apk.sh <serial> <package> [product-dir]
#   product-dir: an s2a-out*/<title>-v<n> directory holding package.json
#                (default: newest under s2a-out-diag/ or s2a-out/)
set -euo pipefail

SERIAL=${1:-}
PKG=${2:-}
PRODUCT=${3:-}

[ -n "$SERIAL" ] && [ -n "$PKG" ] || {
    echo "usage: $0 <serial> <package> [product-dir]" >&2
    exit 2
}

ROOT=$(cd "$(dirname "$0")/.." && pwd)
WORKSPACE=$(cd "$ROOT/.." && pwd)
ADB=${ADB:-adb}
export ADB_MDNS=0
A=("$ADB" -s "$SERIAL")
export JAVA_HOME=${JAVA_HOME:-$HOME/.cmfa-toolchain/jdk}
export ANDROID_HOME=${ANDROID_HOME:-$HOME/.cmfa-toolchain/android-sdk}
export ANDROID_SDK_ROOT=$ANDROID_HOME

if [ -z "$PRODUCT" ]; then
    for candidate in "$WORKSPACE"/s2a-out-diag/*/package.json "$WORKSPACE"/s2a-out/*/package.json; do
        [ -f "$candidate" ] || continue
        [ -z "$PRODUCT" ] || [ "$candidate" -nt "$PRODUCT/package.json" ] && PRODUCT=$(dirname "$candidate")
    done
fi

TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT
ASSETS=$TMP/assets
mkdir -p "$ASSETS"

# Prefer the descriptor shipped inside the installed APK: it matches what the
# device is already running, whatever product directory is lying around.
if "${A[@]}" shell "run-as $PKG cat /dev/null" >/dev/null 2>&1; then
    APK_PATH=$("${A[@]}" shell "pm path $PKG" | tr -d '\r' | sed -n 's/^package://p' | head -1)
    if [ -n "$APK_PATH" ]; then
        "${A[@]}" pull "$APK_PATH" "$TMP/installed.apk" >/dev/null 2>&1 || true
        if [ -f "$TMP/installed.apk" ]; then
            unzip -o -q "$TMP/installed.apk" 'assets/launch.json' -d "$TMP" 2>/dev/null || true
            [ -f "$TMP/assets/launch.json" ] && cp "$TMP/assets/launch.json" "$ASSETS/launch.json"
        fi
    fi
fi
if [ ! -f "$ASSETS/launch.json" ] && [ -n "$PRODUCT" ] && [ -d "$PRODUCT" ]; then
    # Fall back to assembling the descriptor the way s2a/cli.py does.
    python3 - "$PRODUCT" "$ASSETS/launch.json" <<'PY'
import json, sys
src, dst = sys.argv[1], sys.argv[2]
meta = json.load(open(src + '/package.json'))
keys = ('schema', 'title_id', 'bundle_id', 'total_bytes', 'name', 'embedded')
json.dump({k: meta[k] for k in keys if k in meta}, open(dst, 'w'))
PY
fi
[ -f "$ASSETS/launch.json" ] || { echo "no launch.json (installed APK and product dir both empty)" >&2; exit 1; }

# d2r 引擎只在 <files>/games/<title>/shaders/vk 里找 <key>.xgs，game.s2a 里那份
# .spv/.res.json 运行时一个都不读。这些包不随资产发布，空白设备一进 compute dispatch
# 就会 "Dispatch has no genuine compute shader" 直接退出，所以必须打进 APK。
# 生成：tools/pack-shader-bundles.sh
BUNDLES=${S2A_SHADER_BUNDLES:-$WORKSPACE/s2a-work/shader-bundles.zip}
if [ -f "$BUNDLES" ]; then
    cp "$BUNDLES" "$ASSETS/shader-bundles.zip"
    echo "bundles: $BUNDLES ($(wc -c <"$BUNDLES" | tr -d ' ') bytes)"
else
    echo "warning: $BUNDLES 缺失 —— 这个 APK 装到空白设备上会因缺着色器闪退" >&2
fi

# 中文替换字体：native/shared_font.cpp 只在 <files>/games/<title>/ 里找它，系统字体
# 没有中文字形，缺了就是满屏 "?"。以前靠手工 adb push，卸载重装即失，现在随包发。
# 源文件由 tools/make-shared-font.sh 生成。
FONT=${S2A_SHARED_FONT:-$ROOT/assets/shared-font.otf}
if [ -f "$FONT" ]; then
    cp "$FONT" "$ASSETS/shared-font.otf"
    echo "font:   $FONT ($(wc -c <"$FONT" | tr -d ' ') bytes)"
else
    echo "warning: $FONT 缺失 —— 这个 APK 装到空白设备上中文会显示成 ?" >&2
fi

NAME=$(python3 -c 'import json,sys;print(json.load(open(sys.argv[1]))["name"])' "$ASSETS/launch.json")
# The installed version code is authoritative: launch.json records the game's
# own version, not the APK revision, so deriving the code from it produces a
# downgrade the installer rejects. Bump past whatever is on the device.
INSTALLED=$("${A[@]}" shell "dumpsys package $PKG | grep -m1 versionCode" 2>/dev/null | tr -d '\r' | sed -n 's/.*versionCode=\([0-9][0-9]*\).*/\1/p')
[ -n "$INSTALLED" ] || INSTALLED=0
VERSION_CODE=$((INSTALLED + 1))

echo "app id: $PKG"
echo "name:   $NAME"
echo "assets: $ASSETS/launch.json"

cd "$ROOT"
./gradlew --offline \
    -Ps2aAssets="$ASSETS" \
    -Ps2aAppId="$PKG" \
    -Ps2aName="$NAME" \
    -Ps2aVersionCode="$VERSION_CODE" \
    -Ps2aBuildDir="$ROOT/s2a-work/android-build" \
    assembleRelease

APK=$ROOT/s2a-work/android-build/app/outputs/apk/release/app-release.apk
unzip -l "$APK" | grep -q 'assets/launch.json' || { echo "built APK lost launch.json" >&2; exit 1; }
# A stale copy in files/native/ shadows the packaged library (see MainActivity
# .loadNativeHost), so a hot-pushed build would silently win over this one.
"${A[@]}" shell "run-as $PKG rm -f files/native/libot2host.so" 2>/dev/null || true
"${A[@]}" install -r "$APK"

echo "installed $APK"
